-- Repair columns missing from the partially installed initial schema.
alter table public.events add column if not exists internal_notes text;
alter table public.events add column if not exists requested_entertainment text;

-- Activity is generated by the audit trigger and readable only by admins.
alter table public.activity_log enable row level security;
drop policy if exists activity_admin_read on public.activity_log;
create policy activity_admin_read on public.activity_log for select to authenticated
  using (public.has_org_role(organization_id, array['admin']));
notify pgrst, 'reload schema';
